'use client';

import { createContext, useCallback, useContext, useEffect, useLayoutEffect, useRef, useState, type AriaRole, type ReactNode, type Ref, type RefObject } from 'react';
import { Button as AriaButton, Collection, Header, Menu as AriaMenu, MenuContext, MenuItem as AriaMenuItem, MenuSection as AriaMenuSection, MenuTrigger, Popover, PopoverContext, RootMenuTriggerStateContext, Separator, SubmenuTrigger, Text, useSlottedContext } from 'react-aria-components';
import type { ButtonProps as AriaButtonProps, MenuProps, MenuItemProps, MenuSectionProps, MenuTriggerProps, PopoverProps, SubmenuTriggerProps } from 'react-aria-components';
import { RiArrowRightSLine, RiCheckLine } from '@remixicon/react';
import { buttonClassNames, type ButtonSize, type ButtonVariant } from '@/components/base/buttons/button';
import { Kbd } from '@/components/base/kbd/kbd';
import { useMediaQuery } from '@/hooks/use-media-query';
import { ScrollArea } from '@/components/base/scroll-area/scroll-area';
import type { IconComponent } from '@/components/foundations/icon-types';
import { cx } from '@/utils/cx';

const MenuExitContext = createContext(false);
const MenuCloseGuardContext = createContext<RefObject<(() => boolean) | null> | null>(null);
const MenuRestoreFocusContext = createContext<RefObject<(() => void) | null> | null>(null);
const MenuSurfacesContext = createContext<Set<HTMLElement> | null>(null);
export type ActionMenuDensity = 'comfortable' | 'compact';
export type ActionMenuRootProps = MenuTriggerProps & { density?: ActionMenuDensity };
const MenuDensityContext = createContext<ActionMenuDensity>('comfortable');

/** A keyboard accessible action menu. ContextMenu and Menubar share this collection. */
export function ActionMenuRoot({isOpen, defaultOpen = false, onOpenChange, density = 'comfortable', ...props}: ActionMenuRootProps) {
  const [internalOpen, setInternalOpen] = useState(defaultOpen);
  const guard = useRef<(() => boolean) | null>(null);
  const restore = useRef<(() => void) | null>(null);
  const closing = useRef(false);
  const surfaces = useRef(new Set<HTMLElement>());
  return <MenuDensityContext.Provider value={density}><MenuSurfacesContext.Provider value={surfaces.current}><MenuCloseGuardContext.Provider value={guard}><MenuRestoreFocusContext.Provider value={restore}><MenuTrigger {...props} isOpen={isOpen ?? internalOpen} onOpenChange={next => {
    if (!next && guard.current?.()) return;
    if (!next && closing.current) return;
    closing.current = !next;
    try {
      if (!next) restore.current?.();
      if (isOpen === undefined) setInternalOpen(next);
      onOpenChange?.(next);
    } finally { closing.current = false; }
  }}/></MenuRestoreFocusContext.Provider></MenuCloseGuardContext.Provider></MenuSurfacesContext.Provider></MenuDensityContext.Provider>;
}

export type ActionMenuTriggerProps = Omit<AriaButtonProps, 'className' | 'children'> & {
  children: ReactNode;
  className?: string;
  variant?: ButtonVariant;
  size?: ButtonSize;
  ref?: Ref<HTMLButtonElement>;
  role?: AriaRole;
};

export function ActionMenuTrigger({children, className, variant = 'secondary', size = 'medium', onPressStart, role, render, ...props}: ActionMenuTriggerProps) {
  const state = useContext(RootMenuTriggerStateContext);
  const closeOnPointer = useRef(false);
  return <AriaButton {...props} onPressStart={event => {
    onPressStart?.(event);
    // MenuTrigger opens on pointer down. A repeated pointer activation should
    // close it; touch and keyboard already toggle through its public handlers.
    if (closeOnPointer.current && (event.pointerType === 'mouse' || event.pointerType === 'pen')) state?.close();
  }} render={(domProps, renderProps) => {
    const triggerProps = {...domProps, role, onPointerDownCapture: (event: React.PointerEvent<HTMLButtonElement>) => {
      domProps.onPointerDownCapture?.(event);
      closeOnPointer.current = event.currentTarget.getAttribute('aria-expanded') === 'true';
    }};
    return render ? render(triggerProps, renderProps) : <button {...triggerProps}/>;
  }} data-variant={variant} data-size={size} className={buttonClassNames(size, false, cx('ui-action-menu-trigger', className))}>{children}</AriaButton>;
}

export type ActionMenuPopoverProps = Omit<PopoverProps, 'children' | 'className'> & {
  children: ReactNode;
  className?: string;
  density?: ActionMenuDensity;
  width?: 'normal' | 'wide';
};

export function ActionMenuPopover({children, className, density: densityOverride, width = 'normal', offset = 6, isNonModal = true, ...props}: ActionMenuPopoverProps) {
  const inheritedDensity = useContext(MenuDensityContext);
  const density = densityOverride ?? inheritedDensity;
  const guard = useContext(MenuCloseGuardContext);
  const restore = useContext(MenuRestoreFocusContext);
  const state = useContext(RootMenuTriggerStateContext);
  const surfaces = useContext(MenuSurfacesContext);
  const anchor = useSlottedContext(PopoverContext);
  const constrainedSubmenu = useMediaQuery(`(max-width: ${2 * (width === 'wide' ? 320 : 256) + 36}px)`);
  const placement = props.placement ?? (anchor?.trigger === 'SubmenuTrigger' && constrainedSubmenu ? 'bottom start' : undefined);
  const popover = useRef<HTMLElement>(null);
  const setPopover = useCallback((element: HTMLElement | null) => {
    if (popover.current) surfaces?.delete(popover.current);
    popover.current = element;
    if (element) surfaces?.add(element);
  }, [surfaces]);
  useLayoutEffect(() => {
    const trigger = anchor?.triggerRef?.current;
    if (!restore || !trigger || !state?.isOpen || anchor?.trigger === 'SubmenuTrigger') return;
    const restoreFromMenu = () => {
      if ([...(surfaces ?? [])].some(surface => surface.contains(document.activeElement)) && trigger instanceof HTMLElement) trigger.focus({preventScroll: true});
    };
    restore.current = restoreFromMenu;
    return () => { if (restore.current === restoreFromMenu) restore.current = null; };
  }, [anchor?.trigger, anchor?.triggerRef, restore, state?.isOpen, surfaces]);
  useLayoutEffect(() => {
    const trigger = anchor?.triggerRef?.current;
    if (!state?.isOpen || !isNonModal || !trigger || anchor?.trigger === 'SubmenuTrigger') return;
    function dismissOutside(event: PointerEvent) {
      const target = event.target;
      if (!(target instanceof Node) || trigger!.contains(target) || [...(surfaces ?? [])].some(surface => surface.contains(target))) return;
      if (target instanceof Element && props.shouldCloseOnInteractOutside?.(target) === false) return;
      state!.close();
    }
    document.addEventListener('pointerdown', dismissOutside, true);
    return () => document.removeEventListener('pointerdown', dismissOutside, true);
  }, [anchor?.trigger, anchor?.triggerRef, isNonModal, props.shouldCloseOnInteractOutside, state, surfaces]);
  useLayoutEffect(() => {
    const trigger = anchor?.triggerRef?.current;
    if (!guard || !trigger || !state?.isOpen || !isNonModal || anchor?.trigger === 'SubmenuTrigger') return;
    const openedAt = trigger.getBoundingClientRect();
    let unchangedScroll = false;
    let scrollEvent: Event | null = null;
    const ignoreClose = () => unchangedScroll && scrollEvent !== null && scrollEvent.eventPhase !== Event.NONE;
    guard.current = ignoreClose;
    function onScroll(event: Event) {
      if (event.target instanceof Node && !event.target.contains(trigger ?? null)) return;
      const now = trigger!.getBoundingClientRect();
      // A scroll queued before the opening may arrive after it. Only suppress
      // that event's close when the anchor has not actually moved. Real scrolling
      // and every other dismissal remain immediate, with no timer or key delay.
      unchangedScroll = Math.abs(now.x - openedAt.x) < .5 && Math.abs(now.y - openedAt.y) < .5;
      scrollEvent = event;
    }
    window.addEventListener('scroll', onScroll, true);
    return () => { window.removeEventListener('scroll', onScroll, true); if (guard.current === ignoreClose) guard.current = null; };
  }, [anchor?.trigger, anchor?.triggerRef, guard, isNonModal, state?.isOpen]);
  return <Popover {...props} placement={placement} ref={setPopover} isNonModal={isNonModal} offset={offset} data-density={density} data-width={width} className={cx('ui-action-menu-popover', className)}>{({isExiting}) => <MenuDensityContext.Provider value={density}><MenuExitContext.Provider value={isExiting}><div inert={isExiting} className="ui-action-menu-popover__content">{children}</div></MenuExitContext.Provider></MenuDensityContext.Provider>}</Popover>;
}

export type ActionMenuProps<T extends object = object> = Omit<MenuProps<T>, 'className'> & { className?: string; scrollLabel?: string };

export function ActionMenu<T extends object>({className, children, scrollLabel = 'Menu', ...props}: ActionMenuProps<T>) {
  const isExiting = useContext(MenuExitContext);
  const state = useContext(RootMenuTriggerStateContext);
  const contextualProps = useSlottedContext(MenuContext, props.slot);
  const autoFocus = props.autoFocus ?? contextualProps?.autoFocus;
  const viewport = useRef<HTMLDivElement>(null);
  const [mountedMenu, setMountedMenu] = useState<HTMLDivElement | null>(null);
  const scrollViewport = useRef<Ref<HTMLDivElement>>(null);
  const setViewport = useCallback((element: HTMLDivElement | null) => {
    viewport.current = element;
    const ref = scrollViewport.current;
    if (typeof ref === 'function') ref(element); else if (ref) ref.current = element;
    setMountedMenu(element);
  }, []);
  useEffect(() => {
    if (isExiting || !state?.isOpen || !autoFocus) return;
    function focusOnOpening() {
      const menu = viewport.current;
      if (!menu || (menu.contains(document.activeElement) && (document.activeElement !== menu || autoFocus === true))) return;
      const items = [...menu.querySelectorAll<HTMLElement>('.ui-action-menu-item:not([data-disabled])')];
      const target = autoFocus === 'last' ? items.at(-1) : autoFocus === 'first' ? items[0] : menu;
      (target ?? menu).focus({preventScroll: true});
    }
    // Let the overlay initialize its focus scope before moving focus. An
    // outgoing sibling scope can finish in this frame; restore only lost focus
    // and never overwrite navigation already performed inside the new menu.
    focusOnOpening();
    const frame = requestAnimationFrame(focusOnOpening);
    return () => cancelAnimationFrame(frame);
  }, [autoFocus, isExiting, state?.isOpen, mountedMenu]);
  return <ScrollArea label={scrollLabel} className="ui-action-menu-scroll" renderViewport={({ref, className: viewportClassName, children: content}) => {
    scrollViewport.current = ref;
    return <AriaMenu {...props} ref={setViewport} inert={isExiting} className={cx('ui-action-menu', viewportClassName, className)}>{content as MenuProps<T>['children']}</AriaMenu>;
  }}>{children as ReactNode}</ScrollArea>;
}

export type ActionMenuItemProps<T extends object = object> = Omit<MenuItemProps<T>, 'className' | 'children'> & {
  children: ReactNode;
  className?: string;
  icon?: IconComponent;
  shortcut?: ReactNode;
  description?: string;
  variant?: 'default' | 'destructive';
};

export function ActionMenuItem<T extends object>({children, className, icon: Icon, shortcut, description, variant = 'default', ...props}: ActionMenuItemProps<T>) {
  return <AriaMenuItem {...props} textValue={props.textValue ?? (typeof children === 'string' ? children : undefined)} data-variant={variant} className={cx('ui-action-menu-item', className)}>{({isSelected, hasSubmenu, selectionMode}) => <>
    {selectionMode !== 'none' && <span className="ui-action-menu-item__selection" data-selected={isSelected || undefined} aria-hidden><RiCheckLine/></span>}
    {Icon && <Icon className="ui-action-menu-item__icon" aria-hidden/>}
    <span className="ui-action-menu-item__text"><Text slot="label" className="ui-action-menu-item__label">{children}</Text>{description && <Text slot="description" className="ui-action-menu-item__description">{description}</Text>}</span>
    {shortcut && <Kbd className="ui-action-menu-item__shortcut" aria-hidden>{shortcut}</Kbd>}
    {hasSubmenu && <RiArrowRightSLine className="ui-action-menu-item__chevron" aria-hidden/>}
  </>}</AriaMenuItem>;
}

export type ActionMenuSectionProps<T extends object = object> = MenuSectionProps<T> & { label?: string };
export function ActionMenuSection<T extends object>({label, children, className, items, ...props}: ActionMenuSectionProps<T>) {
  return <AriaMenuSection {...props} className={cx('ui-action-menu-section', className)}>{label && <Header className="ui-action-menu-section__label">{label}</Header>}<Collection items={items}>{children}</Collection></AriaMenuSection>;
}

export function ActionMenuSeparator() { return <Separator className="ui-action-menu-separator"/>; }
export function ActionSubmenu(props: SubmenuTriggerProps) { return <SubmenuTrigger {...props}/>; }

'use client';

import type { ButtonHTMLAttributes, ReactNode, Ref } from 'react';
import type { IconComponent } from '@/components/foundations/icon-types';
import { cx } from '@/utils/cx';
import { Spinner } from '@/components/base/spinner/spinner';

export type ButtonVariant = 'primary' | 'secondary' | 'ghost' | 'danger' | 'soft' | 'outline' | 'solid' | 'quiet';
export type ButtonSize = 'medium' | 'small' | 'xs';

type NativeButtonProps = Omit<ButtonHTMLAttributes<HTMLButtonElement>, 'children'>;
type ContentProps =
  | { iconOnly: true; 'aria-label': string; leadingIcon: IconComponent; children?: never }
  | { iconOnly?: false; children: ReactNode; leadingIcon?: IconComponent };

export type ButtonProps = NativeButtonProps & ContentProps & {
  variant?: ButtonVariant;
  size?: ButtonSize;
  trailingIcon?: IconComponent;
  isLoading?: boolean;
  loadingLabel?: string;
  ref?: Ref<HTMLButtonElement>;
};

const base = 'ui-button inline-flex shrink-0 items-center justify-center whitespace-nowrap select-none outline-none';
const sizes: Record<ButtonSize, string> = {
  medium: 'h-9 rounded-[10px] px-2 gap-0.5',
  small: 'h-8 rounded-lg px-2 gap-0.5',
  xs: 'h-6 rounded-[5px] px-2 gap-0.5',
};
export const buttonIconClassNames: Record<ButtonSize, string> = { medium: 'size-5', small: 'size-[18px]', xs: 'size-3.5' };
export function buttonClassNames(size: ButtonSize, iconOnly = false, className?: string) {
  return cx(base, sizes[size], iconOnly && 'ui-button--icon-only !p-0', className);
}

export function Button({
  variant = 'primary',
  size = 'medium',
  iconOnly = false,
  leadingIcon: LeadingIcon,
  trailingIcon: TrailingIcon,
  children,
  className,
  type = 'button',
  isLoading = false,
  loadingLabel,
  disabled,
  onClick,
  onKeyDown,
  ...props
}: ButtonProps) {
  return (
    <button
      {...props}
      type={isLoading && type === 'submit' ? 'button' : type}
      disabled={disabled}
      aria-disabled={isLoading || props['aria-disabled'] || undefined}
      aria-busy={isLoading || undefined}
      aria-description={isLoading && loadingLabel ? loadingLabel : props['aria-description']}
      data-variant={variant}
      data-size={size}
      data-icon-only={iconOnly || undefined}
      data-loading={isLoading || undefined}
      data-loading-label={loadingLabel !== undefined || undefined}
      className={buttonClassNames(size, iconOnly, className)}
      onClick={event => { if (isLoading || props['aria-disabled'] === true || props['aria-disabled'] === 'true') { event.preventDefault(); event.stopPropagation(); return; } onClick?.(event); }}
      onKeyDown={event => { if (isLoading && (event.key === 'Enter' || event.key === ' ')) { event.preventDefault(); event.stopPropagation(); return; } onKeyDown?.(event); }}
    >
      {LeadingIcon && <span className="ui-button__leading-slot" aria-hidden><LeadingIcon className={cx(buttonIconClassNames[size], 'ui-button__leading-icon')}/></span>}
      {!iconOnly && <span className="ui-button__label">{children}</span>}
      {!iconOnly && TrailingIcon && <TrailingIcon className={buttonIconClassNames[size]} aria-hidden />}
      <Spinner className="ui-button__busy-spinner" size={size === 'xs' ? 'xs' : size === 'small' ? 'sm' : 'md'}/>
    </button>
  );
}

'use client';

import {useMemo,useRef,type AnchorHTMLAttributes,type ButtonHTMLAttributes,type Ref} from 'react';
import {mergeRefs} from 'react-aria';
import {useMotionTokens} from '@/hooks/use-motion-tokens';
import { Button as AriaButton, ProgressBar as AriaProgressBar, type ButtonProps as AriaButtonProps } from 'react-aria-components';
import { AnimatePresence, motion } from 'motion/react';
import { useMediaQuery } from '@/hooks/use-media-query';
import { Spinner } from '@/components/base/spinner/spinner';
import type { IconComponent } from '@/components/foundations/icon-types';
import { cx } from '@/utils/cx';

export type IconButtonSize = 'medium' | 'small' | 'xs';

export type IconButtonProps = Omit<ButtonHTMLAttributes<HTMLButtonElement>, 'children' | 'aria-label' | 'onFocus' | 'onBlur' | 'onKeyDown' | 'onKeyUp' | 'onClick'> & Pick<AriaButtonProps, 'onFocus' | 'onBlur' | 'onKeyDown' | 'onKeyUp' | 'onClick' | 'isPending' | 'preventFocusOnPress'> & {
  icon: IconComponent;
  /** Animate a glyph change without moving or remounting its button. */
  iconKey?: string | number;
  pendingLabel?: string;
  size?: IconButtonSize;
  variant?: 'secondary' | 'ghost';
  badge?: number;
  ref?: Ref<HTMLButtonElement>;
  'aria-label': string;
};

export type IconLinkButtonProps = Omit<AnchorHTMLAttributes<HTMLAnchorElement>, 'children' | 'aria-label'> & {
  icon: IconComponent;
  size?: IconButtonSize;
  'aria-label': string;
};

export function IconButton({ icon: Icon, iconKey, pendingLabel = 'Working', isPending, size = 'medium', variant = 'secondary', badge, className, type = 'button', disabled, value, ref, ...props }: IconButtonProps) {
  const reducedMotion = useMediaQuery('(prefers-reduced-motion: reduce)');
  const root=useRef<HTMLButtonElement>(null),composed=useMemo(()=>mergeRefs(root,ref),[ref]),tokens=useMotionTokens(root);
  return <AriaButton {...props} ref={composed} type={type} value={value === undefined ? undefined : String(value)} isDisabled={disabled} isPending={isPending} data-size={size} data-variant={variant} className={cx('ui-icon-button', className)}>{iconKey === undefined ? <Icon className="ui-icon-button__icon" aria-hidden /> : <span className="ui-icon-button__glyph" aria-hidden><AnimatePresence initial={false}><motion.span key={iconKey} data-icon-key={iconKey} initial={reducedMotion ? false : { opacity: 0, scale: .65, y: 2 }} animate={{ opacity: 1, scale: 1, y: 0 }} exit={reducedMotion ? { opacity: 0 } : { opacity: 0, scale: .65, y: -2 }} transition={{ duration: reducedMotion ? 0 : tokens.fast, ease: tokens.ease }}><Icon className="ui-icon-button__icon"/></motion.span></AnimatePresence></span>}<span className="ui-icon-button__pending" aria-hidden><Spinner size={size === 'medium' ? 'md' : 'sm'}/></span>{isPending && <AriaProgressBar aria-label={pendingLabel} isIndeterminate className="sr-only"/>}{badge !== undefined && badge > 0 && <span className="ui-icon-button__badge" aria-hidden>{badge > 99 ? '99+' : badge}</span>}</AriaButton>;
}

export function IconLinkButton({ icon: Icon, size = 'medium', className, ...props }: IconLinkButtonProps) {
  return <a data-size={size} className={cx('ui-icon-button', className)} {...props}><Icon className="ui-icon-button__icon" aria-hidden /></a>;
}

'use client';

import { useContext, type ReactNode, type Ref } from 'react';
import { Button as AriaButton, RootMenuTriggerStateContext, type ButtonProps } from 'react-aria-components';
import { ActionMenuRoot, type ActionMenuRootProps } from '@/components/base/action-menu/action-menu';
import { cx } from '@/utils/cx';

export type ContextMenuProps = Omit<ActionMenuRootProps, 'trigger'>;
/** Right click, touch long press and the platform's keyboard context-menu shortcut. */
export function ContextMenu(props: ContextMenuProps) { return <ActionMenuRoot {...props} trigger="contextMenu"/>; }

export type ContextMenuTriggerProps = Omit<ButtonProps, 'className' | 'children'> & { children: ReactNode; className?: string; ref?: Ref<HTMLButtonElement> };
export function ContextMenuTrigger({className, children, onKeyDown, render, ...props}: ContextMenuTriggerProps) {
  const state = useContext(RootMenuTriggerStateContext);
  return <AriaButton {...props} className={cx('ui-context-menu-trigger', className)} onKeyDown={event => {
    onKeyDown?.(event);
    if (event.defaultPrevented || props.isDisabled || !(event.key === 'ContextMenu' || (event.shiftKey && event.key === 'F10'))) return;
    // Some browsers do not emit the platform contextmenu event for these keys.
    // Feed the standard DOM event to MenuTrigger so its public positioning and
    // pointer behavior remain identical, then focus the first available action.
    event.preventDefault();
    const target = event.currentTarget;
    const rect = target.getBoundingClientRect();
    target.dispatchEvent(new MouseEvent('contextmenu', {bubbles: true, cancelable: true, clientX: rect.left + rect.width / 2, clientY: rect.top + rect.height / 2}));
    state?.open('first');
  }} render={(domProps, renderProps) => {
    const triggerProps = {...domProps, onContextMenuCapture: (event: React.MouseEvent<HTMLButtonElement>) => {
      domProps.onContextMenuCapture?.(event);
      if (props.isDisabled) { event.stopPropagation(); return; }
      event.currentTarget.focus({preventScroll: true});
    }};
    return render ? render(triggerProps, renderProps) : <button {...triggerProps}/>;
  }}>{children}</AriaButton>;
}

export { ActionMenu, ActionMenuItem, ActionMenuPopover, ActionMenuSection, ActionMenuSeparator, ActionSubmenu } from '@/components/base/action-menu/action-menu';

import type { HTMLAttributes } from 'react';
import { cx } from '@/utils/cx';

export type KbdProps = HTMLAttributes<HTMLElement> & {
  variant?: 'soft' | 'outline';
  size?: 'small' | 'medium';
};

export function Kbd({ className, variant = 'soft', size = 'small', ...props }: KbdProps) {
  return <kbd className={cx('ui-kbd', className)} data-variant={variant} data-size={size} {...props} />;
}

/** Supply an aria-label when the visible keys use platform-specific symbols. */
export function KbdGroup({ className, ...props }: HTMLAttributes<HTMLElement>) {
  return <kbd className={cx('ui-kbd-group', className)} {...props}/>;
}

'use client';

import { useCallback, useLayoutEffect, useRef, useState, type ReactElement, type ReactNode, type Ref, type RefObject } from 'react';
import { RiArrowDownSLine, RiArrowUpSLine, RiArrowLeftSLine, RiArrowRightSLine } from '@remixicon/react';
import { IconButton } from '@/components/base/buttons/icon-button';
import { cx } from '@/utils/cx';

export type ScrollAreaViewportProps = { ref: Ref<HTMLDivElement>; className: string; children: ReactNode };
export type ScrollAreaProps = {
  children?: ReactNode;
  label: string;
  className?: string;
  viewportClassName?: string;
  orientation?: 'vertical' | 'horizontal' | 'both';
  /** Let a collection own the scroll viewport, keeping its keyboard scrolling native. */
  renderViewport?: (props: ScrollAreaViewportProps) => ReactElement;
  /** Keep a pointer action in a searchable input without stealing its focus. */
  preservePointerFocus?: boolean;
  /** Restore a virtual collection's input when a focused edge disappears. */
  focusRef?: RefObject<HTMLElement | null>;
  /** Keep arrow controls outside the item viewport in constrained collections. */
  indicatorPlacement?: 'overlay' | 'gutter';
};

/** Keep native scrolling, with directional controls only when content overflows. */
export function ScrollArea({ children, label, className, viewportClassName, renderViewport, orientation = 'vertical', preservePointerFocus = false, focusRef, indicatorPlacement='overlay' }: ScrollAreaProps) {
  const viewport = useRef<HTMLDivElement>(null), content = useRef<HTMLDivElement>(null);
  const [mountedViewport, setMountedViewport] = useState<HTMLDivElement | null>(null);
  const setViewport = useCallback((element: HTMLDivElement | null) => {
    viewport.current = element;
    setMountedViewport(element);
  }, []);
  const [edges, setEdges] = useState({ up: false, down: false, left: false, right: false });
  const measuredEdges = useRef(edges);
  useLayoutEffect(() => {
    const el = mountedViewport;
    if (!el) return;
    function measure() {
      if (!el) return;
      const up = orientation !== 'horizontal' && el.scrollTop > 1, down = orientation !== 'horizontal' && el.scrollHeight - el.clientHeight - el.scrollTop > 1;
      const rtl = getComputedStyle(el).direction === 'rtl', maximum = el.scrollWidth - el.clientWidth;
      const left = orientation !== 'vertical' && (rtl ? maximum + el.scrollLeft : el.scrollLeft) > 1;
      const right = orientation !== 'vertical' && (rtl ? -el.scrollLeft : maximum - el.scrollLeft) > 1;
      const next = { up, down, left, right };
      const focusedEdge = document.activeElement?.closest('.ui-scroll-area__edge');
      const direction = focusedEdge?.getAttribute('data-direction') as keyof typeof next | undefined;
      if (focusedEdge && el.parentElement?.contains(focusedEdge) && direction && !next[direction]) (focusRef?.current ?? el).focus({ preventScroll: true });
      if (Object.keys(next).some(key => measuredEdges.current[key as keyof typeof next] !== next[key as keyof typeof next])) {
        measuredEdges.current = next;
        setEdges(measuredEdges.current);
      }
    }
    const observer = new ResizeObserver(measure);
    const observed = new Set<Element>();
    function observeContent() {
      if (!el) return;
      // A collection may not allow a wrapper between itself and its sections.
      // Observe those sections directly so filtering and density changes are measured.
      const next = new Set<Element>([el, ...el.children]);
      for (const child of observed) if (!next.has(child)) { observer.unobserve(child); observed.delete(child); }
      for (const child of next) if (!observed.has(child)) { observer.observe(child); observed.add(child); }
      measure();
    }
    const mutations = new MutationObserver(observeContent);
    mutations.observe(el, { childList: true, subtree: true });
    observeContent();
    el.addEventListener('scroll', measure, { passive: true });
    return () => { observer.disconnect(); mutations.disconnect(); el.removeEventListener('scroll', measure); };
  }, [focusRef, mountedViewport, orientation]);
  function scroll(direction: number, horizontal = false) {
    const el = viewport.current;
    if (!el) return;
    el.scrollBy({ [horizontal ? 'left' : 'top']: direction * Math.max(80, (horizontal ? el.clientWidth : el.clientHeight) * .7), behavior: window.matchMedia('(prefers-reduced-motion: reduce)').matches ? 'instant' : 'smooth' });
  }
  return <div className={cx('ui-scroll-area', className)} data-orientation={orientation} data-indicator-placement={indicatorPlacement} data-overflow-y={edges.up || edges.down || undefined}>
    {renderViewport ? renderViewport({ ref: setViewport, className: cx('ui-scroll-area__viewport', viewportClassName), children }) : <div ref={setViewport} className={cx('ui-scroll-area__viewport', viewportClassName)} role="region" aria-label={label} tabIndex={0}><div ref={content} className="ui-scroll-area__content">{children}</div></div>}
    <div className="ui-scroll-area__edge" data-direction="up" data-visible={edges.up || undefined} aria-hidden={!edges.up}><IconButton icon={RiArrowUpSLine} variant="ghost" size="xs" preventFocusOnPress={preservePointerFocus} aria-label={`Scroll ${label.toLowerCase()} up`} disabled={!edges.up} tabIndex={edges.up ? 0 : -1} onClick={() => scroll(-1)}/></div>
    <div className="ui-scroll-area__edge" data-direction="down" data-visible={edges.down || undefined} aria-hidden={!edges.down}><IconButton icon={RiArrowDownSLine} variant="ghost" size="xs" preventFocusOnPress={preservePointerFocus} aria-label={`Scroll ${label.toLowerCase()} down`} disabled={!edges.down} tabIndex={edges.down ? 0 : -1} onClick={() => scroll(1)}/></div>
    {orientation !== 'vertical' && <>
      <div className="ui-scroll-area__edge" data-direction="left" data-visible={edges.left || undefined} aria-hidden={!edges.left}><IconButton icon={RiArrowLeftSLine} variant="ghost" size="xs" preventFocusOnPress={preservePointerFocus} aria-label={`Scroll ${label.toLowerCase()} left`} disabled={!edges.left} tabIndex={edges.left ? 0 : -1} onClick={() => scroll(-1, true)}/></div>
      <div className="ui-scroll-area__edge" data-direction="right" data-visible={edges.right || undefined} aria-hidden={!edges.right}><IconButton icon={RiArrowRightSLine} variant="ghost" size="xs" preventFocusOnPress={preservePointerFocus} aria-label={`Scroll ${label.toLowerCase()} right`} disabled={!edges.right} tabIndex={edges.right ? 0 : -1} onClick={() => scroll(1, true)}/></div>
    </>}
  </div>;
}

